-- Applied to prod 2026-10-14; file landed for ledger parity (no re-apply needed).
do $$ declare r record; begin for r in select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind in ('f','p') and not exists(select 1 from unnest(coalesce(p.proconfig,'{}')) c where c like 'search_path=%') and not exists(select 1 from pg_depend d where d.objid=p.oid and d.deptype='e') loop execute format('alter function %s set search_path = public, extensions, pg_temp', r.sig); end loop; end $$;
